-- الدستور الدائم لدولة قطر 2004 - الباب الرابع: تنظيم السلطات (الفصل الأول: السلطة التنفيذية - المواد 59-89)

INSERT INTO qatar_legal_texts (law_type, law_number, year, title_ar, title_en, part_number, part_title, chapter_number, chapter_title, article_number, article_text_ar, keywords, source_url) VALUES

