('constitution', '0/2004', 2004, 'الدستور الدائم لدولة قطر', 'Permanent Constitution of Qatar', '4', 'تنظيم السلطات', '1', 'الأمير', '59',
'الأمير هو رأس الدولة، ذاته مصونة، واحترامه واجب.',
ARRAY['أمير', 'رأس الدولة', 'مصون', 'احترام'], 'https://www.almeezan.qa/'),

('constitution', '0/2004', 2004, 'الدستور الدائم لدولة قطر', 'Permanent Constitution of Qatar', '4', 'تنظيم السلطات', '1', 'الأمير', '60',
'الأمير هو القائد الأعلى للقوات المسلحة. وتكون له الرئاسة العليا عليها، ويعاونه في ذلك مجلس للدفاع يتبعه مباشرة ويُشكل بقرار أميري يحدد اختصاصاته.',
ARRAY['قائد أعلى', 'قوات مسلحة', 'مجلس دفاع'], 'https://www.almeezan.qa/'),

('constitution', '0/2004', 2004, 'الدستور الدائم لدولة قطر', 'Permanent Constitution of Qatar', '4', 'تنظيم السلطات', '1', 'الأمير', '61',
'يُمثل الأمير الدولة في الداخل والخارج وفي جميع العلاقات الدولية.',
ARRAY['تمثيل', 'داخل', 'خارج', 'علاقات دولية'], 'https://www.almeezan.qa/'),

('constitution', '0/2004', 2004, 'الدستور الدائم لدولة قطر', 'Permanent Constitution of Qatar', '4', 'تنظيم السلطات', '1', 'الأمير', '62',
'يُصدر الأمير الأوامر الأميرية بإنشاء وتنظيم الوزارات والأجهزة الحكومية الأخرى وتحديد اختصاصاتها. ويجوز بقرار أميري إلحاق الأجهزة الحكومية بأي من الوزارات أو المؤسسات الحكومية.',
ARRAY['أوامر أميرية', 'وزارات', 'أجهزة حكومية', 'اختصاصات'], 'https://www.almeezan.qa/'),

('constitution', '0/2004', 2004, 'الدستور الدائم لدولة قطر', 'Permanent Constitution of Qatar', '4', 'تنظيم السلطات', '1', 'الأمير', '63',
'يُصدق الأمير على القوانين ويصدرها. ولا يصدر قانون ما لم يُصدق عليه الأمير.',
ARRAY['تصديق', 'قوانين', 'إصدار'], 'https://www.almeezan.qa/'),

('constitution', '0/2004', 2004, 'الدستور الدائم لدولة قطر', 'Permanent Constitution of Qatar', '4', 'تنظيم السلطات', '1', 'الأمير', '64',
'يبرم الأمير المعاهدات والاتفاقيات بمرسوم، ويُبلغها مجلس الشورى مشفوعة بما يناسب من البيان. وتكون للمعاهدة أو الاتفاقية قوة القانون بعد التصديق عليها ونشرها في الجريدة الرسمية. على أنه يجب أن تصدر معاهدات الصلح ومعاهدات الدولة المتعلقة بإقليم الدولة أو بحقوق السيادة أو بحقوق المواطنين العامة أو الخاصة أو المعاهدات المتعلقة بالتنظيم الدولي أو التي تتضمن التزاماً مالياً على خزينة الدولة أو التي يلزم لتنفيذها تشريعات داخلية بقانون.',
ARRAY['معاهدات', 'اتفاقيات', 'مرسوم', 'تصديق', 'مجلس الشورى'], 'https://www.almeezan.qa/'),

('constitution', '0/2004', 2004, 'الدستور الدائم لدولة قطر', 'Permanent Constitution of Qatar', '4', 'تنظيم السلطات', '1', 'الأمير', '65',
'للأمير أن يصدر في غيبة مجلس الشورى مراسيم لها قوة القانون في الظروف الاستثنائية التي تتطلب اتخاذ تدابير عاجلة لا تحتمل التأخير. وتعرض هذه المراسيم بقوانين على مجلس الشورى في أول اجتماع له، وللمجلس في موعد أقصاه أربعون يوماً من تاريخ عرضها عليه وبأغلبية ثلثي أعضائه أن يرفض أياً من هذه المراسيم بقوانين أو أن يطلب تعديلها خلال مدة محددة. ويزول ما كان لها من قوة القانون من تاريخ رفض المجلس لها أو انقضاء مدة التعديل دون إجرائه.',
ARRAY['مراسيم', 'ظروف استثنائية', 'قوة قانون', 'مجلس الشورى'], 'https://www.almeezan.qa/'),

('constitution', '0/2004', 2004, 'الدستور الدائم لدولة قطر', 'Permanent Constitution of Qatar', '4', 'تنظيم السلطات', '1', 'الأمير', '66',
'للأمير إذا طرأت ظروف استثنائية تتطلب اتخاذ تدابير عاجلة تستوجب إعلان الأحكام العرفية أن يصدر مرسوماً بإعلان الأحكام العرفية في البلاد. وفي هذه الحالة له أن يتخذ كل الإجراءات السريعة اللازمة لمواجهة أي خطر يهدد سلامة الدولة أو كيانها أو أمن مواطنيها ومصالحهم أو يعوق مؤسسات الدولة عن أداء مهامها. على أن المرسوم يجب أن يحدد طبيعة تلك الظروف الاستثنائية التي استوجبت إعلان الأحكام العرفية ويبين الإجراءات المتخذة لمواجهتها. ويخطر مجلس الشورى بهذا المرسوم خلال الخمسة عشر يوماً التالية لصدوره. وفي حالة عدم انعقاد المجلس لأي سبب يُخطر المجلس بالمرسوم فور انعقاده. وتكون الأحكام العرفية لمدة محددة ولا يجوز تمديدها إلا بموافقة مجلس الشورى.',
ARRAY['أحكام عرفية', 'ظروف استثنائية', 'تدابير عاجلة', 'مجلس الشورى'], 'https://www.almeezan.qa/'),

('constitution', '0/2004', 2004, 'الدستور الدائم لدولة قطر', 'Permanent Constitution of Qatar', '4', 'تنظيم السلطات', '1', 'الأمير', '67',
'للأمير العفو عن العقوبة أو تخفيفها. ولا يكون العفو الشامل إلا بقانون.',
ARRAY['عفو', 'عقوبة', 'تخفيف', 'قانون'], 'https://www.almeezan.qa/'),

('constitution', '0/2004', 2004, 'الدستور الدائم لدولة قطر', 'Permanent Constitution of Qatar', '4', 'تنظيم السلطات', '1', 'الأمير', '68',
'يُقرر الأمير منح الأوسمة المدنية والعسكرية وفقاً للقانون.',
ARRAY['أوسمة', 'مدنية', 'عسكرية'], 'https://www.almeezan.qa/'),

('constitution', '0/2004', 2004, 'الدستور الدائم لدولة قطر', 'Permanent Constitution of Qatar', '4', 'تنظيم السلطات', '1', 'الأمير', '69',
'يُنشئ الأمير بقرارات أميرية أجهزة تعينه على أداء مهامه الدستورية وفي تسيير شؤون الدولة.',
ARRAY['قرارات أميرية', 'أجهزة', 'مهام دستورية'], 'https://www.almeezan.qa/'),

('constitution', '0/2004', 2004, 'الدستور الدائم لدولة قطر', 'Permanent Constitution of Qatar', '4', 'تنظيم السلطات', '1', 'الأمير', '70',
'يعين الأمير الموظفين المدنيين والعسكريين والممثلين السياسيين ويعزلهم وفقاً للقانون، ويقبل اعتماد الممثلين السياسيين الأجانب.',
ARRAY['تعيين', 'موظفين', 'مدنيين', 'عسكريين', 'سياسيين'], 'https://www.almeezan.qa/');;
